private function extractQuotedSheetNames(string $value, array &$quotedSheetNames): string
{
    return (string) preg_replace_callback(
        self::QUOTED_SHEET_NAME_REGEX,
        function (array $matches) use (&$quotedSheetNames): string {
            $quotedSheetNames[] = $matches[0];

            return "\x00" . (count($quotedSheetNames) - 1) . "\x00";
        },
        $value
    );
}

private function restoreQuotedSheetNames(string $value, array $quotedSheetNames): string
{
    return (string) preg_replace_callback(
        '/\x00(\d+)\x00/',
        fn (array $matches): string => $quotedSheetNames[(int) $matches[1]],
        $value
    );
}

